function simulateWorkerMessage(data) {
  // 結構化複製概念上等同於「深拷貝」，這裡用 JSON 模擬效果
  return JSON.parse(JSON.stringify(data));
}
var mainData = { count: 1, nested: { flag: true } };
var received = simulateWorkerMessage(mainData);
received.nested.flag = false; // 修改「worker 收到的副本」
console.log(mainData.nested.flag); // 主執行緒的原始資料還是同一個嗎？

