function asmModule() {
  'use asm'; // 給支援 asm.js 優化的引擎看的提示
  function add(a, b) {
    a = a | 0;
    b = b | 0;
    return (a + b) | 0;
  }
  return add;
}
var add = asmModule();
console.log(add(2, 3));

